import argparse,csv,hashlib,json,re
from pathlib import Path
p=argparse.ArgumentParser(); p.add_argument("--root",type=Path,required=True); a=p.parse_args(); root=a.root.resolve(); manifest=root/"data/split_manifest.csv"; rows=list(csv.DictReader(manifest.open())); assert len(rows)==2880 and {s:sum(r["split"]==s for r in rows) for s in ("train","val","test")}=={"train":1920,"val":480,"test":480}; assert all((root/r["path"]).is_file() and (root/r["path"]).stat().st_size>0 for r in rows); assert len({r["path"] for r in rows})==2880; assert all(100<=int(r["n"])<180 for r in rows); print(json.dumps({"manifest_sha256":hashlib.sha256(manifest.read_bytes()).hexdigest(),"images":2880,"split_counts":{"train":1920,"val":480,"test":480},"methods":["ordinal_regression","pure_classification"]},indent=2))
